def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    largest = max(v1, v2)

    return {
        "value": largest,
        "trace": {
            "v1": v1,
            "v2": v2,
            "largest_tier_1_capital": largest,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "monetary"
            }
        }
    }
